                    .contentType(ContentType.JSON)
                    .body("{\"username\": \"nouser\", \"password\": \"password\"}")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(400)
                    .body("error", equalTo("Invalid username or password"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
