  "endpoint": {
    "method": "PUT",
    "path": "/api/owners/{ownerId}",
    "controller": "OwnerRestController",
    "controllerFile": "src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java",
    "handler": "updateOwner"
  },
  "className": "OwnerUpdateBlackBoxTest",
  "sqlSlug": "owner-update",
  "docLines": [
    "OwnerRestController.updateOwner: if (!ownerRepository.existsById(ownerId)) return 404; else owner.setId(ownerId); ownerRepository.save(owner); return 200.",
    "existsById(ownerId) is the only real branch -> genuine ATC_updateOwner_notFound (404).",
    "No @Valid on @RequestBody Owner -> bean validation not enforced on update body either (same as createOwner).",
    "@PathVariable Integer ownerId: non-numeric segment triggers Spring's MethodArgumentTypeMismatchException -> 400 (framework-level, high confidence).",
    "detect-external-calls: OwnerRepository REAL (JPA), no external HTTP calls, no WireMock needed."
  ],
  "seedParams": [
    {"name": "SEQ", "kind": "seq"},
    {"name": "LNAME", "kind": "id", "prefix": "bbu"},
    {"name": "MISSING_SEQ", "kind": "seq", "offset": 50000000}
  ],
  "auth": {
    "pattern": "bearer-token",
    "params": {
      "loginPath": "/api/auth/login",
      "bodyJson": {"username": "admin", "password": "password"},
      "tokenJsonPath": "token"
    }
  },
  "fixtures": {
    "preDelete": true,
    "setup": [
      {"table": "owners",
       "values": {"id": {"ref": "SEQ"}, "first_name": "Orig", "last_name": {"refStr": "LNAME"},
                  "address": "Old Address", "city": "OldCity", "telephone": "1111111111"}}
    ],
    "teardown": [
      {"table": "owners", "where": {"id": {"ref": "SEQ"}}}
    ]
  },
  "tests": [
    {
      "name": "NTC_updateOwner_success",
      "pathParams": {"ownerId": "${SEQ}"},
      "jsonBody": {"firstName": "Updated", "lastName": "${LNAME}", "address": "New Address", "city": "NewCity", "telephone": "9999999999"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "firstName", "equalTo": "Updated"},
        {"path": "address", "equalTo": "New Address"},
        {"path": "city", "equalTo": "NewCity"},
        {"path": "telephone", "equalTo": "9999999999"}
      ],
      "dbAssertions": [
        {"query": "SELECT first_name FROM owners WHERE id = ?", "args": ["${SEQ}"], "expectEquals": "Updated"}
      ]
    },
    {
      "name": "NTC_updateOwner_changeAllFields_success",
      "pathParams": {"ownerId": "${SEQ}"},
      "jsonBody": {"firstName": "Franklin", "lastName": "${LNAME}", "address": "110 W. Liberty St.", "city": "Madison", "telephone": "6085551023"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "firstName", "equalTo": "Franklin"},
        {"path": "city", "equalTo": "Madison"}
      ],
      "dbAssertions": [
        {"query": "SELECT telephone FROM owners WHERE id = ?", "args": ["${SEQ}"], "expectEquals": "6085551023"}
      ]
    },
    {
      "name": "NTC_updateOwner_boundaryTelephone",
      "pathParams": {"ownerId": "${SEQ}"},
      "jsonBody": {"firstName": "Bound", "lastName": "${LNAME}", "address": "Edge Rd", "city": "Edgeville", "telephone": "0000000001"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "telephone", "equalTo": "0000000001"}
      ],
      "dbAssertions": [
        {"query": "SELECT telephone FROM owners WHERE id = ?", "args": ["${SEQ}"], "expectEquals": "0000000001"}
      ]
    },
    {
      "name": "ATC_updateOwner_notFound",
      "comment": "existsById(ownerId) returns false for an id with no matching row -> 404",
      "pathParams": {"ownerId": "${MISSING_SEQ}"},
      "jsonBody": {"firstName": "Ghost", "lastName": "Nobody", "address": "N/A", "city": "N/A", "telephone": "0000000000"},
      "expectStatus": 404
    },
    {
      "name": "ATC_updateOwner_invalidIdFormat",
      "comment": "non-numeric ownerId path segment -> Spring MethodArgumentTypeMismatchException -> 400",
      "pathParams": {"ownerId": "abc"},
      "jsonBody": {"firstName": "X", "lastName": "Y", "address": "Z", "city": "Z", "telephone": "0000000000"},
      "expectStatus": 400
    },
    {
      "name": "VTC_updateOwner_blankFields_stillSucceeds",
      "comment": "no @Valid on update body either -> blank required fields still persist and return 200 (documents actual lenient behavior)",
      "pathParams": {"ownerId": "${SEQ}"},
      "jsonBody": {"firstName": "", "lastName": "${LNAME}", "address": "", "city": "", "telephone": ""},
      "expectStatus": 200,
      "expectBody": [
        {"path": "firstName", "equalTo": ""}
      ],
      "dbAssertions": [
        {"query": "SELECT COUNT(*) FROM owners WHERE id = ? AND first_name = ''", "args": ["${SEQ}"], "expectEquals": "1"}
      ]
    }
  ]
}

