package org.springframework.samples.petclinic.blackbox;

import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.queryScalar;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api PUT /api/owners/{ownerId}
 *
 * OwnerRestController.updateOwner: if (!ownerRepository.existsById(ownerId)) return 404; else owner.setId(ownerId); ownerRepository.save(owner); return 200.
 * existsById(ownerId) is the only real branch -> genuine ATC_updateOwner_notFound (404).
 * No @Valid on @RequestBody Owner -> bean validation not enforced on update body either (same as createOwner).
 * @PathVariable Integer ownerId: non-numeric segment triggers Spring's MethodArgumentTypeMismatchException -> 400 (framework-level, high confidence).
 * detect-external-calls: OwnerRepository REAL (JPA), no external HTTP calls, no WireMock needed.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class OwnerUpdateBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "SEQ", Long.toString(seq),
                "LNAME", "bbu" + testId(info),
                "MISSING_SEQ", Long.toString(seq + 50000000));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/owner-update-teardown.sql", p);
        executeSqlTemplate("sql/owner-update-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_updateOwner_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"firstName\": \"Updated\", \"lastName\": \"" + p.get("LNAME") + "\", \"address\": \"New Address\", \"city\": \"NewCity\", \"telephone\": \"9999999999\"}")
            .when()
                    .put("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Updated"))
                    .body("address", equalTo("New Address"))
                    .body("city", equalTo("NewCity"))
                    .body("telephone", equalTo("9999999999"));
            org.junit.jupiter.api.Assertions.assertEquals("Updated", queryScalar("SELECT first_name FROM owners WHERE id = ?", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/owner-update-teardown.sql", p);
        }
    }

    @Test
    void NTC_updateOwner_changeAllFields_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"firstName\": \"Franklin\", \"lastName\": \"" + p.get("LNAME") + "\", \"address\": \"110 W. Liberty St.\", \"city\": \"Madison\", \"telephone\": \"6085551023\"}")
            .when()
                    .put("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Franklin"))
                    .body("city", equalTo("Madison"));
            org.junit.jupiter.api.Assertions.assertEquals("6085551023", queryScalar("SELECT telephone FROM owners WHERE id = ?", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/owner-update-teardown.sql", p);
        }
    }

    @Test
    void NTC_updateOwner_boundaryTelephone(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"firstName\": \"Bound\", \"lastName\": \"" + p.get("LNAME") + "\", \"address\": \"Edge Rd\", \"city\": \"Edgeville\", \"telephone\": \"0000000001\"}")
            .when()
                    .put("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("telephone", equalTo("0000000001"));
            org.junit.jupiter.api.Assertions.assertEquals("0000000001", queryScalar("SELECT telephone FROM owners WHERE id = ?", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/owner-update-teardown.sql", p);
        }
    }

    @Test
    void ATC_updateOwner_notFound(TestInfo info) {
        // existsById(ownerId) returns false for an id with no matching row -> 404
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("MISSING_SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"firstName\": \"Ghost\", \"lastName\": \"Nobody\", \"address\": \"N/A\", \"city\": \"N/A\", \"telephone\": \"0000000000\"}")
            .when()
                    .put("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owner-update-teardown.sql", p);
        }
    }

    @Test
    void ATC_updateOwner_invalidIdFormat(TestInfo info) {
        // non-numeric ownerId path segment -> Spring MethodArgumentTypeMismatchException -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "abc")
                    .contentType(ContentType.JSON)
                    .body("{\"firstName\": \"X\", \"lastName\": \"Y\", \"address\": \"Z\", \"city\": \"Z\", \"telephone\": \"0000000000\"}")
            .when()
                    .put("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-update-teardown.sql", p);
        }
    }

    @Test
    void VTC_updateOwner_blankFields_stillSucceeds(TestInfo info) {
        // no @Valid on update body either -> blank required fields still persist and return 200 (documents actual lenient behavior)
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"firstName\": \"\", \"lastName\": \"" + p.get("LNAME") + "\", \"address\": \"\", \"city\": \"\", \"telephone\": \"\"}")
            .when()
                    .put("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo(""));
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM owners WHERE id = ? AND first_name = ''", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/owner-update-teardown.sql", p);
        }
    }
}

