@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class PetCreateBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "OWNER_SEQ", Long.toString(seq),
                "LNAME", "bbp" + testId(info),
                "MISSING_OWNER_SEQ", Long.toString(seq + 50000000));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/pet-create-teardown.sql", p);
        executeSqlTemplate("sql/pet-create-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_createPet_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("ownerId", p.get("OWNER_SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"Rex\", \"birthDate\": \"2020-01-15\", \"type\": {\"id\": 1, \"name\": \"cat\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(201)
                    .body("name", equalTo("Rex"))
                    .body("birthDate", equalTo("2020-01-15"))
                    .body("type.name", equalTo("cat"))
                    .body("type.id", equalTo(1))
                    .body("id", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("Rex", queryScalar("SELECT name FROM pets WHERE owner_id = ?", p.get("OWNER_SEQ")));
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }

    @Test
    void NTC_createPet_differentTypeAndOwner_success(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("ownerId", p.get("OWNER_SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"Fido\", \"birthDate\": \"2018-06-20\", \"type\": {\"id\": 2, \"name\": \"dog\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(201)
                    .body("name", equalTo("Fido"))
                    .body("type.name", equalTo("dog"))
                    .body("type.id", equalTo(2));
            org.junit.jupiter.api.Assertions.assertEquals("2", queryScalar("SELECT type_id FROM pets WHERE owner_id = ? AND name = ?", p.get("OWNER_SEQ"), "Fido"));
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }

    @Test
    void NTC_createPet_boundaryOldBirthDate(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("ownerId", p.get("OWNER_SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"Ancient\", \"birthDate\": \"1990-01-01\", \"type\": {\"id\": 3, \"name\": \"lizard\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(201)
                    .body("birthDate", equalTo("1990-01-01"))
                    .body("type.name", equalTo("lizard"));
            org.junit.jupiter.api.Assertions.assertEquals("1990-01-01", queryScalar("SELECT birth_date FROM pets WHERE owner_id = ? AND name = ?", p.get("OWNER_SEQ"), "Ancient"));
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }

    @Test
    void ATC_createPet_ownerNotFound(TestInfo info) {
        // ownerOpt.isEmpty() -> 404 (valid Integer format, no matching owner row)
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("ownerId", p.get("MISSING_OWNER_SEQ"))
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"Ghost\", \"birthDate\": \"2020-01-01\", \"type\": {\"id\": 1, \"name\": \"cat\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_NULL(TestInfo info) {
        // ownerId query param entirely omitted -> Spring MissingServletRequestParameterException -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"NoOwner\", \"birthDate\": \"2020-01-01\", \"type\": {\"id\": 1, \"name\": \"cat\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_EMPTY(TestInfo info) {
        // ownerId query param present but empty -> Integer conversion failure -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("ownerId", "")
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"EmptyOwner\", \"birthDate\": \"2020-01-01\", \"type\": {\"id\": 1, \"name\": \"cat\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_INVALID_FORMAT(TestInfo info) {
        // non-numeric ownerId -> MethodArgumentTypeMismatchException -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("ownerId", "abc")
                    .contentType(ContentType.JSON)
                    .body("{\"name\": \"BadOwner\", \"birthDate\": \"2020-01-01\", \"type\": {\"id\": 1, \"name\": \"cat\"}}")
            .when()
                    .post("/api/pets")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/pet-create-teardown.sql", p);
        }
    }
}

