    "handler": "updatePet"
  },
  "className": "PetUpdateBlackBoxTest",
  "sqlSlug": "pet-update",
  "docLines": [
    "PetRestController.updatePet(petId, pet): loops all owners' pets to find by id; if found, sets name/birthDate/type and saves the owning Owner; else 404.",
    "Not-found branch is real code (owner.getPet(petId) == null for every owner) -> ATC_updatePet_notFound.",
    "@PathVariable Integer petId: non-numeric segment -> Spring MethodArgumentTypeMismatchException -> 400 (framework-level).",
    "petId path variable can't meaningfully be NULL/EMPTY as a separate case (an empty segment simply fails route matching, not this handler) -> only INVALID_FORMAT and notFound are modeled, matching the owners-update spec's approach for its Integer path variable.",
    "type.id references pre-existing seed rows from db/mysql/data.sql (types: 1=cat, 2=dog, 3=lizard, 4=snake).",
    "detect-external-calls: OwnerRepository/PetTypeRepository REAL (JPA), no external HTTP calls, no WireMock needed."
  ],
  "seedParams": [
    {"name": "OWNER_SEQ", "kind": "seq"},
    {"name": "PET_SEQ", "kind": "seq", "offset": 20000000},
    {"name": "LNAME", "kind": "id", "prefix": "bbpu"},
    {"name": "MISSING_PET_SEQ", "kind": "seq", "offset": 50000000}
  ],
  "auth": {
    "pattern": "bearer-token",
    "params": {
      "loginPath": "/api/auth/login",
      "bodyJson": {"username": "admin", "password": "password"},
      "tokenJsonPath": "token"
    }
  },
  "fixtures": {
    "preDelete": true,
    "setup": [
      {"table": "owners",
       "values": {"id": {"ref": "OWNER_SEQ"}, "first_name": "PetOwner2", "last_name": {"refStr": "LNAME"},
                  "address": "2 Test Ave", "city": "TestCity2", "telephone": "3334445555"}},
      {"table": "pets",
       "values": {"id": {"ref": "PET_SEQ"}, "name": "OrigPetName", "birth_date": {"expr": "'2019-05-05'"},
                  "type_id": 1, "owner_id": {"ref": "OWNER_SEQ"}}}
    ],
    "teardown": [
      {"table": "pets", "where": {"id": {"ref": "PET_SEQ"}}},
      {"table": "owners", "where": {"id": {"ref": "OWNER_SEQ"}}}
    ]
  },
  "tests": [
    {
      "name": "NTC_updatePet_success",
      "pathParams": {"petId": "${PET_SEQ}"},
      "jsonBody": {"name": "Rexy", "birthDate": "2021-02-02", "type": {"id": 2, "name": "dog"}},
      "expectStatus": 200,
      "expectBody": [
        {"path": "name", "equalTo": "Rexy"},
        {"path": "birthDate", "equalTo": "2021-02-02"},
        {"path": "type.name", "equalTo": "dog"},
        {"path": "type.id", "equalToInt": 2}
      ],
      "dbAssertions": [
        {"query": "SELECT name FROM pets WHERE id = ?", "args": ["${PET_SEQ}"], "expectEquals": "Rexy"}
      ]
    },
    {
      "name": "NTC_updatePet_changeType_success",
      "pathParams": {"petId": "${PET_SEQ}"},
      "jsonBody": {"name": "Lizzy", "birthDate": "2017-03-03", "type": {"id": 3, "name": "lizard"}},
      "expectStatus": 200,
      "expectBody": [
        {"path": "name", "equalTo": "Lizzy"},
        {"path": "type.name", "equalTo": "lizard"},
        {"path": "type.id", "equalToInt": 3}
      ],
      "dbAssertions": [
        {"query": "SELECT type_id FROM pets WHERE id = ?", "args": ["${PET_SEQ}"], "expectEquals": "3"}
      ]
    },
    {
      "name": "NTC_updatePet_boundaryOldBirthDate",
      "pathParams": {"petId": "${PET_SEQ}"},
      "jsonBody": {"name": "Slither", "birthDate": "1990-01-01", "type": {"id": 4, "name": "snake"}},
      "expectStatus": 200,
      "expectBody": [
        {"path": "birthDate", "equalTo": "1990-01-01"},
        {"path": "type.name", "equalTo": "snake"}
      ],
      "dbAssertions": [
        {"query": "SELECT birth_date FROM pets WHERE id = ?", "args": ["${PET_SEQ}"], "expectEquals": "1990-01-01"}
      ]
    },
    {
      "name": "ATC_updatePet_notFound",
      "comment": "no owner's pet list contains this id -> 404",
      "pathParams": {"petId": "${MISSING_PET_SEQ}"},
      "jsonBody": {"name": "Ghost", "birthDate": "2020-01-01", "type": {"id": 1, "name": "cat"}},
      "expectStatus": 404
    },
    {
      "name": "ATC_updatePet_invalidIdFormat",
      "comment": "non-numeric petId path segment -> Spring MethodArgumentTypeMismatchException -> 400",
      "pathParams": {"petId": "abc"},
      "jsonBody": {"name": "X", "birthDate": "2020-01-01", "type": {"id": 1, "name": "cat"}},
      "expectStatus": 400
    }
  ]
}

