package org.springframework.samples.petclinic.blackbox;

import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller VetController (src/main/java/org/springframework/samples/petclinic/vet/VetController.java)
 * @target-api GET /vets
 *
 * VetController.showResourcesVetList: returns ALL vets unpaginated (Vets wrapper -> JSON {"vetList":[...]}), no request parameters, no error branch.
 * SecurityConfig: only /api/** is .authenticated(); /vets falls through to anyRequest().permitAll() -> no Authorization header needed (verified by reading SecurityConfig source directly; analyze-auth-flow's generic required_headers=[Authorization] is a false positive here since it does not evaluate per-URL matcher precedence).
 * No fixtures: relies on baseline seed data from db/mysql/data.sql (idempotent INSERT IGNORE, always present) - vets/specialties are read-only reference data for this endpoint (no vet CRUD endpoint exists among the 8 assigned endpoints), so no dynamic per-test rows are created.
 * List assertions use GPath find{} on known static seed rows (Carter/Douglas/Ortega) instead of list size(), since size() would be flaky under @Execution(CONCURRENT) if any future test seeds additional vets.
 * detect-external-calls: VetRepository REAL (JPA), no external calls, no WireMock needed. No real error branch exists for this handler -> no ATC.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class VetsListBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/vets-list-teardown.sql", p);
        executeSqlTemplate("sql/vets-list-setup.sql", p);
    }

    @Test
    void NTC_showVetList_vetWithoutSpecialty(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/vets")
            .then()
                    .statusCode(200)
                    .body("vetList.find { it.lastName == 'Carter' }.firstName", equalTo("James"))
                    .body("vetList.find { it.lastName == 'Carter' }.nrOfSpecialties", equalTo(0));
        } finally {
            executeSqlTemplate("sql/vets-list-teardown.sql", p);
        }
    }

    @Test
    void NTC_showVetList_vetWithTwoSpecialties(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/vets")
            .then()
                    .statusCode(200)
                    .body("vetList.find { it.lastName == 'Douglas' }.firstName", equalTo("Linda"))
                    .body("vetList.find { it.lastName == 'Douglas' }.specialties[0].name", equalTo("dentistry"))
                    .body("vetList.find { it.lastName == 'Douglas' }.specialties[1].name", equalTo("surgery"))
                    .body("vetList.find { it.lastName == 'Douglas' }.nrOfSpecialties", equalTo(2));
        } finally {
            executeSqlTemplate("sql/vets-list-teardown.sql", p);
        }
    }

    @Test
    void NTC_showVetList_vetWithOneSpecialty(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .get("/vets")
            .then()
                    .statusCode(200)
                    .body("vetList.find { it.lastName == 'Ortega' }.firstName", equalTo("Rafael"))
                    .body("vetList.find { it.lastName == 'Ortega' }.specialties[0].name", equalTo("surgery"))
                    .body("vetList.find { it.lastName == 'Ortega' }.nrOfSpecialties", equalTo(1));
        } finally {
            executeSqlTemplate("sql/vets-list-teardown.sql", p);
        }
    }
}

