package org.springframework.samples.petclinic.blackbox;

import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller VetRestController (src/main/java/org/springframework/samples/petclinic/vet/VetRestController.java)
 * @target-api GET /api/vets
 *
 * VetRestController.getAllVets(specialty): optional query param; if present+non-empty, filters vets whose specialties (case-insensitive contains) match -> real business branch.
 * Returns Collection<Vet> directly as a JSON array (not wrapped, unlike GET /vets's Vets.vetList wrapper).
 * analyze-auth-flow + SecurityConfig: /api/** is .authenticated() -> Authorization: Bearer <jwt> required (auth.pattern=bearer-token).
 * No fixtures: relies on baseline seed data from db/mysql/data.sql (vets/specialties are read-only reference data for this endpoint).
 * detect-external-calls: VetRepository REAL (JPA), no external calls, no WireMock needed.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class VetApiListBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/vets-api-list-teardown.sql", p);
        executeSqlTemplate("sql/vets-api-list-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_getAllVets_noFilter(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
            .when()
                    .get("/api/vets")
            .then()
                    .statusCode(200)
                    .body("find { it.lastName == 'Carter' }.firstName", equalTo("James"));
        } finally {
            executeSqlTemplate("sql/vets-api-list-teardown.sql", p);
        }
    }

    @Test
    void NTC_getAllVets_filterBySpecialty_surgery(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("specialty", "surgery")
            .when()
                    .get("/api/vets")
            .then()
                    .statusCode(200)
                    .body("find { it.lastName == 'Douglas' }.firstName", equalTo("Linda"))
                    .body("find { it.lastName == 'Ortega' }.firstName", equalTo("Rafael"));
        } finally {
            executeSqlTemplate("sql/vets-api-list-teardown.sql", p);
        }
    }

    @Test
    void NTC_getAllVets_filterCaseInsensitive_upperCase(TestInfo info) {
        // specialty.toLowerCase().contains(specialty.toLowerCase()) -> case-insensitive match
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("specialty", "RADIOLOGY")
            .when()
                    .get("/api/vets")
            .then()
                    .statusCode(200)
                    .body("find { it.lastName == 'Leary' }.firstName", equalTo("Helen"))
                    .body("find { it.lastName == 'Stevens' }.firstName", equalTo("Henry"));
        } finally {
            executeSqlTemplate("sql/vets-api-list-teardown.sql", p);
        }
    }

    @Test
    void VTC_specialty_noMatch_emptyResult(TestInfo info) {
        // specialty value matching no existing specialty name -> filtered result is an empty array
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("specialty", "nonexistentxyz")
            .when()
                    .get("/api/vets")
            .then()
                    .statusCode(200)
                    .body("size()", equalTo(0));
        } finally {
            executeSqlTemplate("sql/vets-api-list-teardown.sql", p);
        }
    }
}

