        executeSqlTemplate("sql/vets-api-get-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_getVet_found_noSpecialty(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("vetId", "1")
            .when()
                    .get("/api/vets/{vetId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("James"))
                    .body("lastName", equalTo("Carter"))
                    .body("nrOfSpecialties", equalTo(0));
        } finally {
            executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
        }
    }

    @Test
    void NTC_getVet_found_withOneSpecialty(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("vetId", "5")
            .when()
                    .get("/api/vets/{vetId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Henry"))
                    .body("lastName", equalTo("Stevens"))
                    .body("specialties[0].name", equalTo("radiology"))
                    .body("nrOfSpecialties", equalTo(1));
        } finally {
            executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
        }
    }

    @Test
    void NTC_getVet_found_withTwoSpecialties(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("vetId", "3")
            .when()
                    .get("/api/vets/{vetId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Linda"))
                    .body("lastName", equalTo("Douglas"))
                    .body("specialties[0].name", equalTo("dentistry"))
                    .body("specialties[1].name", equalTo("surgery"))
                    .body("nrOfSpecialties", equalTo(2));
        } finally {
            executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
        }
    }

    @Test
    void ATC_getVet_notFound_returnsEmptyBody200(TestInfo info) {
        // no vet with this id -> findFirst().orElse(null) -> controller returns null -> 200 with empty body (NOT 404)
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("vetId", p.get("MISSING_SEQ"))
            .when()
                    .get("/api/vets/{vetId}")
            .then()
                    .statusCode(200);;
        } finally {
            executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
        }
    }

    @Test
    void VTC_vetId_INVALID_FORMAT(TestInfo info) {
        // non-numeric vetId path segment -> Spring MethodArgumentTypeMismatchException -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("vetId", "abc")
            .when()
                    .get("/api/vets/{vetId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
        }
    }
}

